package com.example.swikareduapp.database

import androidx.room.Entity
import androidx.room.PrimaryKey

/**
 * Entity class representing the "users" table in the Room database.
 */
@Entity(tableName = "users")
data class User(
    /** Primary key for each user record, auto-generated by Room. */
    @PrimaryKey(autoGenerate = true)
    val id: Int = 0,

    /** The user's name or display name. */
    val username: String,

    /** The user's current game level. Defaults to "1". */
    val level: String = "1",

    /** The user's total score. Defaults to 0. */
    val score: Int = 0,

    /** Total game duration or session time in seconds. Defaults to 0. */
    val duration: Int = 0,

    /** Timestamp when the record was created. Defaults to system current time. */
    val date: Long = System.currentTimeMillis()
)
